using System.Globalization;
using Scada.Engineering.VisualScripting;

namespace Scada.Api.Runtime;

public static partial class ContextualHelpCatalog
{
    private sealed record VisualGuideText(LocalizedText Name, LocalizedText Purpose, LocalizedText Example);
    private sealed record VisualFieldText(LocalizedText Name, LocalizedText Description, string Example);

    private static IEnumerable<ContextualHelpTopic> BuildVisualObjectGuides(string locale)
    {
        foreach (var schema in BuiltinVisualObjectSchemas.All)
        {
            var guide = VisualGuideTexts[schema.ObjectTypeKey];
            var fields = schema.Properties.Values.Where(property => property.EngineeringEditable)
                .Select(property => DescribeVisualField(property, locale)).ToArray();
            yield return new ContextualHelpTopic(
                VisualObjectTopicId(schema.ObjectTypeKey), "visual-objects", guide.Name.For(locale), guide.Purpose.For(locale),
                new[]
                {
                    new ContextualHelpSection(Pick(locale, "Quando escolher este objeto", "When to choose this object", "Cuándo elegir este objeto"), guide.Purpose.For(locale)),
                    new ContextualHelpSection(Pick(locale, "Monte um exemplo pequeno", "Build a small example", "Prepare un ejemplo pequeño"), guide.Example.For(locale)),
                    new ContextualHelpSection(Pick(locale, "Campos deste objeto", "Fields for this object", "Campos de este objeto"), Pick(locale,
                        "Selecione o objeto no desenho. Se estiver atrás de outro, use a Estrutura, a lista dos objetos da tela. Abra o Inspetor, o painel de ajustes do objeto selecionado. Ele organiza campos em grupos e mostra as opções aplicáveis.\n\nConsulte a tabela para entender um ajuste e seu exemplo. Valores iniciais, opções e limites vêm do próprio produto. A chave técnica, dentro da referência, é útil ao escrever um Script para essa propriedade; não é um valor que você precise inventar para desenhar.",
                        "Select the object in the drawing. If it is behind another, use Structure, the screen's object list. Open Inspector, the selected object's settings panel. It groups fields and shows applicable options.\n\nUse the table to understand a setting and its example. Initial values, options and limits come from the product. The technical key inside the reference is useful when writing a Script for that property; it is not a value you must invent to draw.",
                        "Seleccione el objeto en el dibujo. Si está detrás de otro, use Estructura, la lista de objetos de la pantalla. Abra Inspector, el panel de ajustes del objeto elegido. Agrupa campos y muestra opciones aplicables.\n\nUse la tabla para entender un ajuste y su ejemplo. Valores iniciales, opciones y límites vienen del producto. La clave técnica dentro de la referencia sirve para un Script de esa propiedad; no es un valor que deba inventar para dibujar."), Fields: fields),
                    new ContextualHelpSection(Pick(locale, "Conectar ao processo e conferir", "Connect to the process and check", "Conectar al proceso y comprobar"), Pick(locale,
                        "Comece com um valor fixo para conferir a aparência. Depois configure o vínculo de dados ou a ação no painel correspondente. Alterar uma cor ou um valor de apresentação não grava um TAG de processo. Execute a Pré-visualização, leia os diagnósticos, aplique a edição e siga Salvar, Publicar e Ativar. No Runtime, confira também valor ausente, qualidade ruim e limite de escala; aparência bonita não comprova que a medição está disponível.",
                        "Start with a fixed value to check appearance. Then configure the data binding or action in its corresponding panel. Changing a display color or value does not write a process TAG. Run Preview, read diagnostics, apply the edit, and follow Save, Publish and Activate. In Runtime, also check missing values, bad quality and scale limits; appearance does not prove that a measurement is available.",
                        "Empiece con un valor fijo para comprobar el aspecto. Después configure el vínculo de datos o la acción en su panel. Cambiar un color o valor de presentación no escribe un TAG de proceso. Ejecute la Vista previa, lea los diagnósticos, aplique la edición y siga Guardar, Publicar y Activar. En Runtime, compruebe también valores ausentes, mala calidad y límites de escala; el aspecto no demuestra que la medición esté disponible."))
                }.Concat(StructuralVisualSections(schema.ObjectTypeKey, locale)).ToArray(),
                new[] { "visual.properties", "visual.dynamics", "visual.events", "scripts.client-recipes", "screens.overview", "popups.overview" });
        }
    }

    public static string VisualObjectTopicId(string objectType) => $"visual.object.{objectType.ToLowerInvariant()}";

    private static ContextualHelpField DescribeVisualField(VisualPropertyDefinition property, string locale)
    {
        var text = VisualFieldTexts[property.Key];
        var constraints = new List<string>
        {
            $"{Pick(locale, "Inicial", "Initial", "Inicial")}: {VisualDefault(property.DefaultValue)}"
        };
        if (property.Unit is not null) constraints.Add($"{Pick(locale, "Unidade", "Unit", "Unidad")}: {property.Unit}");
        if (property.Constraints.Minimum is double minimum) constraints.Add($"≥ {minimum.ToString("G", CultureInfo.InvariantCulture)}");
        if (property.Constraints.Maximum is double maximum) constraints.Add($"≤ {maximum.ToString("G", CultureInfo.InvariantCulture)}");
        if (property.Constraints.AllowedValues.Count > 0)
            constraints.Add($"{Pick(locale, "Opções", "Options", "Opciones")}: {string.Join(", ", property.Constraints.AllowedValues)}");
        if (!property.RuntimeWritable) constraints.Add(Pick(locale, "Sem alteração por Script no Runtime", "Not writable by Runtime Script", "Sin escritura por Script en Runtime"));
        if (!property.SupportsBinding) constraints.Add(Pick(locale, "Sem vínculo dinâmico", "No dynamic binding", "Sin vínculo dinámico"));
        return new(property.Key, text.Name.For(locale), text.Description.For(locale), text.Example, string.Join(" · ", constraints));
    }

    private static string VisualDefault(VisualPropertyValue value) => value switch
    {
        VisualBooleanValue item => item.Value ? "true" : "false",
        VisualNumberValue item => item.Value.ToString("G", CultureInfo.InvariantCulture),
        VisualIntegerValue item => item.Value.ToString(CultureInfo.InvariantCulture),
        VisualStringValue item => item.Value.Length == 0 ? "—" : item.Value,
        VisualColorValue item => item.Value,
        VisualAssetReferenceValue item => item.AssetId ?? "—",
        VisualResourceReferenceValue item => item.ResourceId,
        _ => throw new InvalidOperationException("Unsupported Help property value.")
    };

    private static IEnumerable<ContextualHelpSection> StructuralVisualSections(string type, string locale)
    {
        if (type == BuiltinVisualObjectSchemas.TrendType)
            yield return new(Pick(locale, "Séries do gráfico", "Chart series", "Series del gráfico"), Pick(locale,
                "Além da aparência, configure cada série (pena): escolha o TAG, dê um nome reconhecível, selecione cor e eixo. Use eixos diferentes para grandezas de unidades distintas, como pressão em bar e corrente em A. O modo histórico exige captura no Historian; aumentar a janela da tela não cria amostras antigas. O modo ao vivo apresenta o acompanhamento corrente. O período de atualização muda a consulta/apresentação, não a frequência de aquisição do Driver.",
                "Besides appearance, configure each series (pen): choose its TAG, give it a recognizable name, and choose color and axis. Use different axes for different units, such as pressure in bar and current in A. History mode requires Historian capture; increasing the screen window does not create past samples. Live mode follows current values. The refresh period changes the query/display, not Driver acquisition frequency.",
                "Además del aspecto, configure cada serie: elija el TAG, asigne un nombre reconocible, color y eje. Use ejes diferentes para unidades distintas, como presión en bar y corriente en A. El modo histórico requiere captura Historian; ampliar la ventana no crea muestras antiguas. El modo en vivo sigue los valores actuales. La actualización cambia la consulta/presentación, no la frecuencia de adquisición del Driver."));
        if (type is BuiltinVisualObjectSchemas.AlarmBrowserType or BuiltinVisualObjectSchemas.EventBrowserType)
            yield return new(Pick(locale, "Conteúdo e filtros", "Content and filters", "Contenido y filtros"), Pick(locale,
                "Configure as colunas e filtros no editor do navegador. O navegador de alarmes apresenta condições e seu estado; o navegador de eventos apresenta ocorrências. Uma cor da linha não altera o estado do alarme. Ações como reconhecimento dependem da permissão da sessão. Para histórico, confira período e fuso; sem registros, retire um filtro por vez antes de concluir que não houve ocorrência.",
                "Configure columns and filters in the browser editor. The alarm browser shows conditions and their states; the event browser shows occurrences. A row color does not change alarm state. Actions such as acknowledgement require session permission. For history, check period and timezone; if empty, remove one filter at a time before concluding that no event occurred.",
                "Configure columnas y filtros en el editor del navegador. El navegador de alarmas muestra condiciones y estados; el de eventos muestra ocurrencias. El color de una fila no cambia el estado de alarma. Acciones como reconocimiento requieren permiso de sesión. En histórico, compruebe período y zona horaria; quite un filtro cada vez antes de concluir que no hubo eventos."));
        if (type == BuiltinVisualObjectSchemas.PolygonType)
            yield return new(Pick(locale, "Pontos e preenchimento", "Points and fill", "Puntos y relleno"), Pick(locale,
                "Os vértices definem o contorno. Se os segmentos se cruzarem, evenodd e nonzero podem preencher regiões diferentes: confira o resultado no desenho. Mover o objeto altera sua posição; editar vértices altera a forma.",
                "Vertices define the outline. When edges cross, evenodd and nonzero can fill different regions: check the drawing. Moving the object changes its position; editing vertices changes its shape.",
                "Los vértices definen el contorno. Si los segmentos se cruzan, evenodd y nonzero pueden rellenar regiones diferentes: compruebe el dibujo. Mover el objeto cambia su posición; editar vértices cambia su forma."));
        if (type == BuiltinVisualObjectSchemas.CheckBoxType)
            yield return new(Pick(locale, "Uso da caixa de seleção", "CheckBox behavior", "Uso de la casilla"), Pick(locale,
                "A caixa é um controle Booleano genérico: pode indicar qualquer fonte booleana compatível, como TAG ou expressão. No modo Booleano do processo, vincule `checked` à fonte escolhida pelo nome. Deixe Permitir ajuste pelo operador desligado para somente observar; para alterar, habilite a interação e use um TAG gravável. A supressão de um alarme é um modo opcional separado: selecione a definição pelo nome, informe motivo e duração e deixe a autorização ser validada pelo Runtime. Qualidade ruim, fonte ausente ou solicitação recusada não significam que a mudança foi concluída.",
                "The CheckBox is a generic Boolean control: it can display any compatible Boolean source, such as a TAG or an expression. In Process Boolean mode, bind `checked` to the source selected by name. Leave Allow operator adjustment off for display only; to change the value, enable interaction and use a writable TAG. Suppressing one alarm is a separate optional mode: select its definition by name, provide a reason and duration, and let Runtime enforce authorization. Bad quality, a missing source or a rejected request do not mean the change succeeded.",
                "La casilla es un control Booleano genérico: puede mostrar cualquier fuente Booleana compatible, como un TAG o una expresión. En modo Booleano del proceso, vincule `checked` a la fuente elegida por nombre. Deje Permitir ajuste del operador desactivado para solo observar; para cambiar el valor, habilite interacción y use un TAG escribible. Suprimir una alarma es un modo opcional separado: seleccione la definición por nombre, indique motivo y duración y deje que Runtime valide la autorización. Mala calidad, fuente ausente o solicitud rechazada no significan que el cambio se haya completado."));
        if (type == BuiltinVisualObjectSchemas.ComboBoxType)
            yield return new(Pick(locale, "Opções e seleção", "Options and selection", "Opciones y selección"), Pick(locale,
                "Cadastre ao menos uma opção com o valor gravado no TAG e o rótulo que o operador verá. Depois vincule `text` a um TAG String ou Enum. O valor atual precisa corresponder a uma opção; valor ausente, lista inválida, qualidade ruim ou tipo incompatível deixam o controle sem escrita. Para permitir escolha, habilite Permitir ajuste pelo operador e use um TAG gravável.",
                "Add at least one option with the value written to the TAG and the label shown to the operator. Then bind `text` to a String or Enum TAG. The current value must match an option; a missing value, invalid list, bad quality or incompatible type leaves the control read-only. To allow selection, enable Allow operator adjustment and use a writable TAG.",
                "Agregue al menos una opción con el valor guardado en el TAG y la etiqueta que verá el operador. Después vincule `text` a un TAG String o Enum. El valor actual debe coincidir con una opción; un valor ausente, lista inválida, mala calidad o tipo incompatible deja el control sin escritura. Para permitir la selección, habilite Permitir ajuste del operador y use un TAG escribible."));
        if (type.StartsWith("core.intelligence", StringComparison.Ordinal))
            yield return new(Pick(locale, "Referências geradas e solicitação de análise", "Generated references and analysis requests", "Referencias generadas y solicitud de análisis"), Pick(locale,
                "Crie este objeto pelo fluxo guiado de Inteligência para que equipamento, perfil, regra e versão fiquem ligados corretamente. Essas referências são preenchidas pelo produto; não copie IDs de outro projeto nem altere o JSON por tentativa. A edição de posição/aparência não executa a análise. No Runtime, escolha o período e solicite a consulta explicitamente; leia os avisos de dados insuficientes antes de interpretar o resultado.",
                "Create this object through the Intelligence guided flow so Equipment, profile, rule and version are linked correctly. The product fills those references; do not copy IDs from another project or guess JSON changes. Editing position/appearance does not run analysis. In Runtime, choose the time window and explicitly request the query; read insufficient-data notices before interpreting results.",
                "Cree este objeto mediante el flujo guiado de Inteligencia para vincular equipo, perfil, regla y versión correctamente. El producto completa las referencias; no copie IDs de otro proyecto ni cambie JSON por prueba. Editar posición/aspecto no ejecuta análisis. En Runtime, elija el período y solicite explícitamente la consulta; lea los avisos de datos insuficientes antes de interpretar el resultado."));
    }

