    private static VisualGuideText VG(string pt, string en, string es, string pp, string ep, string sp, string px, string ex, string sx) => new(Tx(pt, en, es), Tx(pp, ep, sp), Tx(px, ex, sx));
    private static VisualGuideText MG(string pt, string en, string es, string p, string e, string s) => new(Tx(pt, en, es),
        Tx($"Apresenta uma medição numérica por {p}; a escala e a unidade dão contexto ao valor.", $"Presents a numeric measurement using a {e}; the scale and unit give the value context.", $"Presenta una medición numérica mediante {s}; escala y unidad dan contexto al valor."),
        Tx("Vincule o valor, defina mínimo/máximo e unidade; por exemplo, 0–10 bar. Mantenha indicação de qualidade e atualização visível. As faixas e o alvo são referências visuais: não criam Alarm nem escrevem um setpoint.", "Bind the value and set minimum/maximum and unit, for example 0–10 bar. Keep quality and freshness visible. Bands and target are visual references: they do not create an Alarm or write a setpoint.", "Vincule el valor y defina mínimo/máximo y unidad, por ejemplo 0–10 bar. Mantenga visibles calidad y actualización. Bandas y objetivo son referencias visuales: no crean Alarm ni escriben una consigna."));
    private static VisualGuideText IG(string pt, string en, string es) => new(Tx(pt, en, es),
        Tx("Apresenta uma consulta de Inteligência solicitada pelo operador para equipamento e período definidos.", "Shows an operator-requested Intelligence query for a defined Equipment and time window.", "Presenta una consulta de Inteligencia solicitada por el operador para un equipo y período definidos."),
        Tx("Gere a tela a partir de um perfil ou etapa configurados na área de Inteligência. Depois ajuste o layout no editor e confira o comportamento para período sem dados.", "Generate the screen from a configured Intelligence profile or stage. Then adjust layout in the editor and check a period without data.", "Genere la pantalla desde un perfil o etapa configurados en Inteligencia. Después ajuste el diseño en el editor y compruebe un período sin datos."));

